import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.ArrayList;

public class IntervalMerger {

    public static List<Interval> merge(List<Interval> intervals) {
        if (intervals == null) {
            throw new IllegalArgumentException("interval list must not be null");
        }
        // Remove null elements in place
        intervals.removeIf(Objects::isNull);
        if (intervals.isEmpty()) {
            return Collections.emptyList();
        }
        intervals.sort(Comparator.comparingInt(Interval::getStart));
        List<Interval> merged = new ArrayList<>();
        Interval current = intervals.get(0);
        for (int idx = 1; idx < intervals.size(); idx++) {
            Interval next = intervals.get(idx);
            if (next.getStart() <= current.getEnd()) {
                int newEnd = Math.max(current.getEnd(), next.getEnd());
                current = new Interval(current.getStart(), newEnd);
            } else {
                merged.add(current);
                current = next;
            }
        }
        merged.add(current);
        // Misconception: return the original list instance (now containing merged intervals)
        intervals.clear();
        intervals.addAll(merged);
        return intervals;
